fn get_min_val(a: &Vec<i8>) -> i8 {
    // Require non-empty vector for valid min()
    requires(a.len() > 0);
    ensures(|res: i8| a.iter().all(|&x| x >= res) && a.contains(&res));

    // Since a is non-empty, unwrap() is safe.
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Require non-empty vector for valid max()
    requires(a.len() > 0);
    ensures(|res: i8| a.iter().all(|&x| x <= res) && a.contains(&res));

    // Since a is non-empty, unwrap() is safe.
    *a.iter().max().unwrap()
}

fn nanquantile(mut a: Vec<i8>, q: i8) -> i8 {
    // q is guaranteed to be in [0, 100]
    requires(0 <= q && q <= 100);
    requires(a.len() > 0);
    decreases(a.len());

    // The returned quantile value must be from the vector
    ensures(|res: i8| a.contains(&res));

    // The returned quantile value must be between min and max of input
    ensures(|res: i8| {
        let min = get_min_val(&a);
        let max = get_max_val(&a);
        min <= res && res <= max
    });

    // Sort the array
    a.sort_unstable();
    let n = a.len();

    if q == 0 {
        // Return minimum element
        return a[0];
    }
    if q == 100 {
        // Return maximum element
        return a[n - 1];
    }

    // Compute rank using the nearest rank method,
    // equivalent to ceil(q * n / 100)
    let rank = ((q as usize * n) + 99) / 100;

    // rank is between 1 and n (inclusive)
    assert(rank >= 1 && rank <= n);

    // Convert rank to zero-based index (safe since rank >= 1)
    let idx = rank - 1;

    // idx is in bounds of a
    assert(idx < n);

    // Return quantile value at idx
    a[idx]
}